class ThemeQueryCatalogJenaOracleTest {

	private static final int FIRST_DISABLED_QUERY_INDEX = 11;
	private static final int SPARSE_FIRST_DISABLED_QUERY_INDEX = 2;

	@TestFactory
	Stream<DynamicTest> themeQueriesMatchJenaCountsAndCountBindings() {
		return Stream.of(Theme.values())
				.filter(ThemeQueryCatalogJenaOracleTest::matchesThemeFilter)
				.map(theme -> dynamicTest(theme.name(), () -> verifyThemeQueries(theme)));
	}

	private static void verifyThemeQueries(Theme theme) throws Throwable {
		Dataset dataset = jenaDatasetFor(theme);
		try {
			List<String> mismatches = new ArrayList<>();
			List<BenchmarkQuery> queries = ThemeQueryCatalog.benchmarkQueriesFor(theme);
			for (int index : queryIndexesFor(theme, queries)) {
				BenchmarkQuery query = queries.get(index);
				String label = label(theme, index, query);
				System.out.println("Jena oracle: " + label);
				dataset.begin(ReadWrite.READ);
				try {
					verifyQueryMatchesJena(theme, index, query, executeSelect(query, dataset), mismatches);
				} finally {
					dataset.end();
				}
			}
			assertTrue(mismatches.isEmpty(), () -> String.join(System.lineSeparator(), mismatches));
		} finally {
			dataset.close();
		}
	}

	private static void verifyQueryMatchesJena(Theme theme, int index, BenchmarkQuery query, JenaResult result,
			List<String> mismatches) {
		String label = label(theme, index, query);
		if (query.getExpectedCount() != result.rows()) {
			mismatches.add(label + " row count expected " + query.getExpectedCount() + " but was " + result.rows());
		}

		OptionalLong expectedCountBindingValue = ThemeQueryCatalog.expectedCountBindingValueFor(theme, index);
		if (expectedCountBindingValue.isPresent()) {
			if (result.rows() != 1) {
				mismatches.add(label + " aggregate row count expected 1 but was " + result.rows());
			}
			if (result.countValue().isEmpty()) {
				mismatches.add(label + " did not project ?count");
			} else if (expectedCountBindingValue.getAsLong() != result.countValue().getAsLong()) {
				mismatches.add(label + " ?count expected " + expectedCountBindingValue.getAsLong() + " but was "
						+ result.countValue().getAsLong());
			}
		}
	}

	private static String label(Theme theme, int index, BenchmarkQuery query) {
		return theme + " query " + index + " (" + query.getName() + ")";
	}

	private static JenaResult executeSelect(BenchmarkQuery query, Dataset dataset) {
		long rows = 0;
		OptionalLong countValue = OptionalLong.empty();
		try (QueryExecution queryExecution = QueryExecution.dataset(dataset)
				.query(query.getQuery())
				.set(ARQ.spillToDiskThreshold, 1024L)
				.build()) {
			ResultSet resultSet = queryExecution.execSelect();
			while (resultSet.hasNext()) {
				QuerySolution solution = resultSet.nextSolution();
				rows++;
				if (solution.contains("count")) {
					RDFNode countNode = solution.get("count");
					assertTrue(countNode.isLiteral(), query.getName() + " projected non-literal ?count: " + countNode);
					countValue = OptionalLong.of(countNode.asLiteral().getLong());
				}
			}
		}
		return new JenaResult(rows, countValue);
	}

	private static boolean matchesThemeFilter(Theme theme) {
		String filter = System.getProperty("rdf4j.jenaOracle.theme");
		return filter == null || filter.isBlank() || theme.name().equals(filter);
	}

	private static int[] queryIndexesFor(Theme theme, List<BenchmarkQuery> queries) {
		int enabledQueryCount = Math.min(firstDisabledQueryIndex(theme), queries.size());
		String filter = System.getProperty("rdf4j.jenaOracle.query");
		if (filter == null || filter.isBlank()) {
			return IntStream.range(0, enabledQueryCount).toArray();
		}
		return Arrays.stream(filter.split(","))
				.map(String::trim)
				.filter(value -> !value.isEmpty())
				.mapToInt(Integer::parseInt)
				.filter(index -> index >= 0 && index < queries.size())
				.toArray();
	}

	private static int firstDisabledQueryIndex(Theme theme) {
		if (theme == Theme.SPARSE) {
			return SPARSE_FIRST_DISABLED_QUERY_INDEX;
		}
		return FIRST_DISABLED_QUERY_INDEX;
	}

	private static Dataset jenaDatasetFor(Theme theme) throws Throwable {
		Dataset dataset = DatasetFactory.createTxnMem();
		try {
			dataset.begin(ReadWrite.WRITE);
			try {
				org.apache.jena.rdf.model.Model jenaModel = dataset.getDefaultModel();
				if (isVirtualCatalogTheme(theme)) {
					addPhysicalThemeDataset(dataset, jenaModel);
				} else {
					ThemeDataSetGenerator.generate(theme, new AbstractRDFHandler() {
						@Override
						public void handleStatement(Statement statement) {
							jenaModel.add(resource(jenaModel, statement.getSubject()),
									jenaModel.createProperty(statement.getPredicate().stringValue()),
									rdfNode(jenaModel, statement.getObject()));
						}
					});
				}
				dataset.commit();
			} catch (Throwable failure) {
				cleanUpOwnedWrite(failure, dataset::abort, dataset::end);
				throw failure;
			}
			dataset.end();
			return dataset;
		} catch (Throwable failure) {
			cleanUpOwnedWrite(failure, dataset::close);
			throw failure;
		}
	}

	private static boolean isVirtualCatalogTheme(Theme theme) {
		return theme == Theme.ANALYTICS || theme == Theme.EXPLORATION;
	}

	private static void addPhysicalThemeDataset(Dataset dataset, Model defaultModel) {
		Set<String> expectedGraphNames = new HashSet<>();
		long emittedStatements = 0L;
		for (Theme physicalTheme : Arrays.stream(Theme.values())
				.filter(candidate -> !isVirtualCatalogTheme(candidate))
				.toList()) {
			String graphName = graphName(physicalTheme);
			assertTrue(expectedGraphNames.add(graphName), "Physical theme graph names are unique");
			Model namedModel = dataset.getNamedModel(graphName);
			long[] graphStatements = { 0L };
			ThemeDataSetGenerator.generate(physicalTheme, new AbstractRDFHandler() {
				@Override
				public void handleStatement(Statement statement) {
					assertTrue(statement.getContext() instanceof IRI,
							physicalTheme + " statements retain their named graph context");
					assertEquals(graphName, statement.getContext().stringValue(),
							physicalTheme + " statement context");
					addStatement(defaultModel, statement);
					addStatement(namedModel, statement);
					graphStatements[0] = Math.addExact(graphStatements[0], 1L);
				}
			});
			assertTrue(graphStatements[0] > 0L, physicalTheme + " contributes physical statements");
			assertTrue(namedModel.size() > 0L, physicalTheme + " retains a populated named RDF graph");
			emittedStatements = Math.addExact(emittedStatements, graphStatements[0]);
		}

		Set<String> actualGraphNames = new HashSet<>();
		dataset.listNames().forEachRemaining(actualGraphNames::add);
		assertEquals(expectedGraphNames, actualGraphNames,
				"Every physical theme is present in exactly one named graph");
		assertTrue(emittedStatements > 0L, "The combined fixture receives physical statement callbacks");
		assertDefaultIsNamedGraphUnion(dataset, defaultModel);
	}

	private static void assertDefaultIsNamedGraphUnion(Dataset dataset, Model defaultModel) {
		dataset.listNames()
				.forEachRemaining(graphName -> assertTrue(
						defaultModel.containsAll(dataset.getNamedModel(graphName)),
						"Default graph contains every RDF triple from " + graphName));
		// containsAll iterates its argument, so this probes the union with bound triples from the default model.
		assertTrue(dataset.getUnionModel().containsAll(defaultModel),
				"Default graph contains only triples from the deduplicated named-graph union");
	}

	@Test
	void namedGraphUnionChecksDeduplicateAndRejectMissingOrExtraTriples() throws Throwable {
		Dataset dataset = DatasetFactory.createTxnMem();
		Throwable failure = null;
		boolean begun = false;
		try {
			dataset.begin(ReadWrite.WRITE);
			begun = true;
			Model defaultModel = dataset.getDefaultModel();
			Model first = dataset.getNamedModel("urn:union:first");
			Model second = dataset.getNamedModel("urn:union:second");
			var subject = defaultModel.createResource("urn:union:subject");
			var predicate = defaultModel.createProperty("urn:union:predicate");
			var shared = defaultModel.createResource("urn:union:shared");
			var other = defaultModel.createResource("urn:union:other");
			var extra = defaultModel.createResource("urn:union:extra");
			first.add(subject, predicate, shared);
			first.add(subject, predicate, shared);
			second.add(subject, predicate, shared);
			second.add(subject, predicate, other);
			defaultModel.add(first).add(second);
			assertEquals(1L, first.size());
			assertEquals(2L, second.size());
			assertEquals(2L, defaultModel.size());
			assertDefaultIsNamedGraphUnion(dataset, defaultModel);

			defaultModel.remove(subject, predicate, other);
			AssertionError missing = assertThrows(AssertionError.class,
					() -> assertDefaultIsNamedGraphUnion(dataset, defaultModel));
			assertTrue(missing.getMessage().startsWith("Default graph contains every RDF triple from "));
			defaultModel.add(subject, predicate, other);
			defaultModel.add(subject, predicate, extra);
			AssertionError unexpected = assertThrows(AssertionError.class,
					() -> assertDefaultIsNamedGraphUnion(dataset, defaultModel));
			assertTrue(unexpected.getMessage().startsWith("Default graph contains only triples from "));
			defaultModel.remove(subject, predicate, extra);
			assertDefaultIsNamedGraphUnion(dataset, defaultModel);
		} catch (Throwable thrown) {
			failure = thrown;
			throw thrown;
		} finally {
			if (begun) {
				cleanUpOwnedWrite(failure, dataset::abort, dataset::end, dataset::close);
			} else {
				cleanUpOwnedWrite(failure, dataset::close);
			}
		}
	}

	private static void cleanUpOwnedWrite(Throwable primary, Runnable... actions) throws Throwable {
		Throwable failure = primary;
		for (Runnable action : actions) {
			try {
				action.run();
			} catch (Throwable thrown) {
				if (failure == null) {
					failure = thrown;
				} else if (failure != thrown) {
					failure.addSuppressed(thrown);
				}
			}
		}
		if (primary == null && failure != null) {
			throw failure;
		}
	}

	@Test
	void ownedWriteCleanupPreservesBodyFailureAndAttemptsEveryStage() {
		for (Throwable primary : List.of(new IllegalStateException("body"), new AssertionError("body"))) {
			List<String> stages = new ArrayList<>();
			RuntimeException abortFailure = new IllegalArgumentException("abort");
			Error endFailure = new AssertionError("end");
			RuntimeException closeFailure = new IllegalStateException("close");
			Throwable actual = assertThrows(Throwable.class, () -> {
				try {
					throw primary;
				} finally {
					cleanUpOwnedWrite(primary, () -> {
						stages.add("abort");
						throw abortFailure;
					}, () -> {
						stages.add("end");
						throw endFailure;
					}, () -> {
						stages.add("close");
						throw closeFailure;
					});
				}
			});
			assertSame(primary, actual);
			assertEquals(List.of("abort", "end", "close"), stages);
			assertEquals(List.of(abortFailure, endFailure, closeFailure), Arrays.asList(actual.getSuppressed()));
		}
	}

	@Test
	void ownedWriteCleanupThrowsFirstFailureAndSuppressesLaterFailures() {
		for (Throwable first : List.of(new IllegalStateException("abort"), new AssertionError("abort"))) {
			List<String> stages = new ArrayList<>();
			Error endFailure = new AssertionError("end");
			RuntimeException closeFailure = new IllegalStateException("close");
			Throwable actual = assertThrows(Throwable.class, () -> cleanUpOwnedWrite(null, () -> {
				stages.add("abort");
				if (first instanceof RuntimeException exception) {
					throw exception;
				}
				throw (Error) first;
			}, () -> {
				stages.add("end");
				throw endFailure;
			}, () -> {
				stages.add("close");
				throw closeFailure;
			}));
			assertSame(first, actual);
			assertEquals(List.of("abort", "end", "close"), stages);
			assertEquals(List.of(endFailure, closeFailure), Arrays.asList(actual.getSuppressed()));
		}
	}

	@Test
	void ownedWriteCleanupDoesNotSelfSuppressOrSkipStages() {
		Error primary = new AssertionError("body and cleanup");
		List<String> stages = new ArrayList<>();
		Throwable actual = assertThrows(Throwable.class, () -> {
			try {
				throw primary;
			} finally {
				cleanUpOwnedWrite(primary, () -> {
					stages.add("abort");
					throw primary;
				}, () -> {
					stages.add("end");
					throw primary;
				}, () -> {
					stages.add("close");
					throw primary;
				});
			}
		});
		assertSame(primary, actual);
		assertEquals(List.of("abort", "end", "close"), stages);
		assertEquals(0, actual.getSuppressed().length);
	}

	private static String graphName(Theme theme) {
		return "http://example.com/theme/graph/" + theme.name().toLowerCase(Locale.ROOT).replace('_', '-');
	}

	private static void addStatement(Model model, Statement statement) {
		model.add(resource(model, statement.getSubject()),
				model.createProperty(statement.getPredicate().stringValue()), rdfNode(model, statement.getObject()));
	}

	private static RDFNode rdfNode(org.apache.jena.rdf.model.Model model, Value value) {
		if (value instanceof Resource resource) {
			return resource(model, resource);
		}
		if (value instanceof Literal literal) {
			return literal(literal);
		}
		throw new IllegalArgumentException("Unsupported RDF4J value " + value);
	}

	private static org.apache.jena.rdf.model.Resource resource(org.apache.jena.rdf.model.Model model,
			Resource resource) {
		if (resource instanceof IRI iri) {
			return model.createResource(iri.stringValue());
		}
		if (resource instanceof BNode bNode) {
			return model.createResource(AnonId.create(bNode.getID()));
		}
		throw new IllegalArgumentException("Unsupported RDF4J resource " + resource);
	}

	private static RDFNode literal(Literal literal) {
		Optional<String> language = literal.getLanguage();
		if (language.isPresent()) {
			return ResourceFactory.createLangLiteral(literal.getLabel(), language.get());
		}
		RDFDatatype datatype = TypeMapper.getInstance().getSafeTypeByName(literal.getDatatype().stringValue());
		return ResourceFactory.createTypedLiteral(literal.getLabel(), datatype);
	}

	private record JenaResult(long rows, OptionalLong countValue) {
	}
}
